import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, expect, it } from 'vitest';
import { documentMeta, expandVariables, frontMatterBlock, splitSignature } from '../src/meta';
import { renderMarkdown } from '../src/render';

// Same cases as the Go module (mlcext/testdata/meta.json, generated by
// `go test -run TestMetaVectors -update` there).
interface Vector {
  markdown: string;
  meta: { docId: string; version: string; title: string };
  expanded: string;
  signature: { form: string; fields: Record<string, string> } | null;
  content: string;
  stored: string;
}
const vectors: Vector[] = JSON.parse(readFileSync(resolve(process.cwd(), '../../mlcext/testdata/meta.json'), 'utf8'));

describe('meta vectors (shared with mlcext)', () => {
  vectors.forEach((v, i) => {
    it(`case ${i}`, () => {
      expect(documentMeta(v.markdown)).toEqual(v.meta);
      expect(expandVariables(v.markdown)).toBe(v.expanded);
      const s = splitSignature(v.markdown);
      expect(s.content).toBe(v.content);
      expect(s.signature ? { form: s.signature.form, fields: s.signature.fields } : null).toEqual(v.signature);
      // What is rendered is the stored text without its front matter.
      const stored = splitSignature(expandVariables(v.markdown));
      const body = frontMatterBlock(stored.signature?.form === 'end' ? stored.content : expandVariables(v.markdown)).body;
      expect(v.stored.endsWith(body)).toBe(true);
    });
  });
});

describe('render with meta and signature', () => {
  it('variables replaced, signature not shown, meta returned, lines kept', () => {
    const md = vectors[3].markdown;
    const r = renderMarkdown(md);
    expect(r.meta).toEqual({ docId: 'SOP-QM-001', version: '1.0', title: '' });
    expect(r.signature?.fields.signed_by).toBe('Dr. Anna Berger');
    expect(r.html).toContain('Inhalt SOP-QM-001');
    expect(r.html).not.toMatch(/mlc-signature|ed25519/);
    expect(r.html).toContain('data-line="5"');
  });

  it('old signature form in front: own front matter is read, lines from the file', () => {
    const r = renderMarkdown(vectors[4].markdown);
    expect(r.signature?.form).toBe('front');
    expect(r.meta.title).toBe('Alt');
    expect(r.frontMatter).toContain('doc_id: SOP-QM-001');
    expect(r.html).toMatch(/<h1 data-line="13" id="alt">Alt<\/h1>/);
  });
});
